const $=s=>document.querySelector(s);const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sources=[
['Ontology overview','ontology/overview','The operational layer: semantics, kinetics, and applications.'],['Core concepts','ontology/core-concepts','Separate type definitions from individual instances.'],['Object types','object-link-types/object-types-overview','Model entities and events with identity and properties.'],['Link types','object-link-types/link-types-overview','Bidirectional relationships and their backing data.'],['Action types','action-types/overview','Reusable definitions for governed business changes.'],['Submission criteria','action-types/submission-criteria','Control when an action can be submitted.'],['Action rules','action-types/rules','Translate action parameters into edits and effects.'],['Functions on objects','functions/functions-on-objects','Code that operates on objects and object sets.'],['Object sets (TSv1 reference)','functions/api-object-sets','Filtering, traversal, and aggregation; version-specific API.'],['Interfaces','interfaces/interface-overview','Abstract contracts; support differs by application and language.'],['How edits are applied','object-edits/how-edits-applied','How source data and user edits contribute to object state.'],['Consistency and isolation','action-types/consistency-guarantees','Atomic object edits, write modes, and concurrency.'],['External-system action patterns','action-types/explore-action-types','Webhook versus writeback-webhook behavior.'],['Object & property security','object-permissioning/object-security-policies','Read access at object and property granularity.'],['Access-control propagation','security/access-control-propagation','Mandatory controls versus read-time filtering.'],['Developer toolchain / OSDK','dev-toolchain','Generated SDKs and application access to Ontology capabilities.'],['AIP Logic','logic','LLM-powered functions, testing, and operational workflows.'],['Models','model-integration/models','Prediction and optimization artifacts operationalized in Foundry.'],['Indexing restrictions','object-indexing/data-restrictions','Primary-key uniqueness and type coherence in OSv2.'],['Action test runs','action-types/test-run','External calls may still execute during platform test runs.'],['Ontology system architecture','architecture-center/ontology-system','The larger architecture around the Ontology.']];
const cite=i=>`<a class="source-link" href="https://www.palantir.com/docs/foundry/${sources[i][1]}" target="_blank" rel="noreferrer">↗ ${sources[i][0]}</a>`;
const nodes=[{id:'supplier',type:'SUPPLIER',name:'Meridian Components',symbol:'◇',x:90,y:90,props:{supplierId:'SUP-001',region:'East Asia',status:'Disrupted'},desc:'A specific supplier object. ERP supplier records are mapped to a stable business identity.',source:'erp_suppliers'}, {id:'part',type:'PART',name:'Power module P-24',symbol:'▣',x:325,y:90,props:{partId:'P-24',category:'Power electronics',unitValue:'$400'},desc:'A part is shared context across sourcing, inventory, shipments, and orders.',source:'product_master'}, {id:'shipment',type:'SHIPMENT',name:'Inbound SHP-208',symbol:'↗',x:90,y:265,props:{shipmentId:'SHP-208',baseArrival:'Day 2',delay:'3 days'},desc:'A shipment is an operational entity with its own identity and changing state.',source:'tms_shipments'}, {id:'inventory',type:'INVENTORY POSITION',name:'Rotterdam stock',symbol:'▤',x:325,y:265,props:{inventoryId:'INV-RTM-P24',available:'320 units',partId:'P-24'},desc:'An inventory position has a composite business grain: one part at one warehouse. Reallocation consumes this stock.',source:'wms_inventory'}, {id:'order',type:'CUSTOMER ORDER',name:'Order ORD-1042',symbol:'▱',x:560,y:165,props:{orderId:'ORD-1042',quantity:'180 units',due:'Day 3'},desc:'One customer commitment. Link traversal exposes which upstream disruption affects its fulfillment.',source:'erp_orders'}];
const edges=[['supplier','part','supplies'],['supplier','shipment','dispatches'],['shipment','part','carries'],['part','inventory','stocked as'],['part','order','required by'],['inventory','order','can fulfill']];
let selected='part',mode='instances',committed=false,events=[],plan=null,quizAnswers={};
function graph(){const typeNames={supplier:'Supplier',part:'Part',shipment:'Shipment',inventory:'InventoryPosition',order:'CustomerOrder'};return `<svg viewBox="0 0 740 355" role="img" aria-label="Supply-chain object graph. Select an object using its button or the table below."><title>Connected business objects</title>${edges.map(([a,b,label])=>{const n=nodes.find(n=>n.id===a),m=nodes.find(n=>n.id===b);return `<line x1="${n.x+80}" y1="${n.y}" x2="${m.x+80}" y2="${m.y}"/><text class="edge-label" x="${(n.x+m.x)/2+80}" y="${(n.y+m.y)/2-10}" text-anchor="middle">${label}</text>`}).join('')}${nodes.map(n=>`<g class="node ${selected===n.id?'selected':''}" role="button" tabindex="0" aria-label="Inspect ${mode==='schema'?typeNames[n.id]:n.name}" data-node="${n.id}" transform="translate(${n.x-10},${n.y-31})"><rect width="180" height="63" rx="4"/><text class="symbol" x="13" y="37">${n.symbol}</text><text class="type" x="40" y="23">${mode==='schema'?'OBJECT TYPE':n.type}</text><text x="40" y="42">${mode==='schema'?typeNames[n.id]:n.name}</text></g>`).join('')}</svg>`}
function inspector(){const n=nodes.find(n=>n.id===selected);const props={...n.props};if(committed&&plan){if(n.id==='inventory')props.available=(320-plan.quantity)+' units';if(n.id==='shipment')props.delay=plan.delay+' days';if(n.id==='order')props.allocation=plan.result.rescued.some(o=>o.id==='ORD-1042')?'Protected locally':'No alternate allocation';}return `<div class="tag">${mode==='schema'?'SCHEMA DEFINITION':'OBJECT INSTANCE'} / ${n.type}</div><h3>${mode==='schema'?n.type.toLowerCase().replaceAll(' ',' '):n.name}</h3><p>${mode==='schema'?'A reusable definition of identity and properties. Instances follow this contract.':n.desc}</p>${Object.entries(props).map(([k,v])=>`<div class="kv"><span>${k}</span><span>${mode==='schema'?(k.includes('Id')?'string / ID':k==='quantity'?'integer':'property'):v}</span></div>`).join('')}<p>BACKING DATA<br><code>${n.source}</code></p>`}
function world(){return `<div class="world"><div class="world-head"><span>THE CONNECTED ENTERPRISE</span><span>● FICTIONAL SUPPLY CHAIN</span></div><div class="world-body"><div class="graph">${graph()}</div><aside class="inspector">${inspector()}</aside></div><div class="world-foot"><span>◇ Objects = business entities</span><span>― Links = business relationships</span><span>Select a node to inspect →</span></div></div>`}
function bindGraph(){document.querySelectorAll('[data-node]').forEach(n=>{const activate=()=>{selected=n.dataset.node;$('.graph').innerHTML=graph();$('.inspector').innerHTML=inspector();bindGraph()};n.onclick=activate;n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}}})}
function intro(num,title,lede){return `<div class="eyebrow">CHAPTER ${num} / THE ONTOLOGY FIELD GUIDE</div><h1>${title}</h1><p class="lede">${lede}</p>`}
const pages={overview(){return `<div class="hero-row"><div>${intro('01','A world model.<br>Built to <em>take action.</em>','Understand Palantir’s Ontology: the shared operational layer connecting your data, business logic, and decisions to the world they describe.')}<div class="actions"><a href="#explorer" class="btn primary">Explore the Ontology <span>↗</span></a><a href="#decisions" class="btn">Run the disruption demo <span>→</span></a></div></div><div class="stamp">ONE RUNNING EXAMPLE<br>5 object types<br>3 customer orders<br>1 operational decision</div></div>${world()}<div class="section-heading"><h2>Three ideas. One operating model.</h2><span>THE MENTAL MODEL</span></div><div class="three"><article class="concept"><span class="num">01 / SEMANTICS</span><h3>What exists?</h3><p>Objects represent things and events. Properties describe them. Links give them business context.</p><a href="#explorer">Explore the shared language →</a></article><article class="concept"><span class="num">02 / KINETICS</span><h3>What can change?</h3><p>Functions express logic. Action types define reusable changes that operators or applications can submit.</p><a href="#decisions">Make an operational decision →</a></article><article class="concept"><span class="num">03 / GOVERNANCE</span><h3>Who can see and do?</h3><p>Access controls govern reads. Action authorization and submission criteria govern permitted changes.</p><a href="#architecture">Look under the surface →</a></article></div><div class="callout">Think in business commitments: “Which customer orders are threatened, and how can we protect them?”<p>The Ontology gives that question a shared model and a path to action. This site is an independent conceptual simulation, with no Palantir runtime or live AI.</p></div><p>${cite(0)}</p>`},
explorer(){return `${intro('02','From rows to<br><em>real-world meaning.</em>','Switch between the schema and its instances. Inspect a node, then trace how a shipment delay connects to a customer commitment.')}<div class="toolbar"><div class="segmented" aria-label="Graph mode"><button data-mode="instances" class="${mode==='instances'?'active':''}" aria-pressed="${mode==='instances'}">Object instances</button><button data-mode="schema" class="${mode==='schema'?'active':''}" aria-pressed="${mode==='schema'}">Type definitions</button></div><span class="mono" style="font-size:10px">SAME MODEL / TWO LEVELS</span></div>${world()}<div class="section-heading"><h2>The objects behind the picture</h2><label><span class="sr-label">Filter objects </span><input type="search" id="search" placeholder="Search type, ID, or name…" aria-label="Filter objects"></label></div><div class="table-wrap"><table><thead><tr><th>Object type</th><th>Identity / primary key</th><th>Instance</th><th>Inspect</th></tr></thead><tbody id="objects">${objectRows('')}</tbody></table></div><div class="three" style="margin-top:30px"><article class="concept"><span class="num">IDENTITY</span><h3>Type ≠ instance</h3><p>CustomerOrder is the definition. ORD-1042 is a specific object. A stable primary key lets the same object survive source refreshes.</p>${cite(1)}</article><article class="concept"><span class="num">RELATIONSHIPS</span><h3>A link has two sides</h3><p>“Part required by orders” and “Order requires part” are traversals of the same link type. Diagram direction expresses this story, not a one-way API restriction.</p>${cite(3)}</article><article class="concept"><span class="num">REUSE</span><h3>One contract, many types</h3><p>A Locatable interface could be implemented by Supplier and Warehouse. Shared properties and capabilities let compatible workflows work across types.</p>${cite(9)}</article></div><div class="callout">Modeling note: “can fulfill” is an illustrative candidate relationship.<p>A production model would usually represent an allocation as its own object when quantity, status, and provenance belong to the relationship. See the study guide for the richer schema.</p></div>`},
decisions(){return `${intro('03','See the impact.<br><em>Change the outcome.</em>','A delayed shipment threatens three orders. Query the connected context, simulate alternate stock, and apply a governed reallocation. All figures and policy rules are fictional.')}<div class="split"><section class="panel"><div class="eyebrow">01 / EXPLORE A POSSIBLE DECISION</div><h2>Supply disruption workbench</h2><p class="bodycopy">Expected inbound arrival is day 2. Orders are late when arrival exceeds their due day. Whole orders receive alternate stock in due-date order.</p><label class="field">Shipment delay <strong id="delay-value">3 days</strong><input type="range" id="delay" min="0" max="7" value="3"></label><label class="field">Alternate units to allocate <strong id="qty-value">320 units</strong><input type="range" id="qty" min="0" max="420" step="20" value="320"></label><p class="bodycopy">320 units available in Rotterdam • $12 transport cost / allocated unit. Unused reserved units still incur transport cost in this simplified model.</p><div id="projection"></div></section><section class="panel"><div class="eyebrow">02 / SUBMIT A BUSINESS ACTION</div><h2>Reallocate inventory</h2><p class="bodycopy">One action captures the operational intent. This teaching policy permits planners to reserve available stock and record a reason.</p><label class="field">Acting as<select id="role"><option value="planner">Operations planner — can apply</option><option value="analyst">Analyst — read only</option></select></label><label class="field">Decision reason<input type="text" id="reason" value="Protect customer commitments" maxlength="160"></label><button class="btn primary" id="apply">Apply reallocation <span>↗</span></button><button class="btn" id="reset">Reset demo</button><div id="validation" role="status" aria-live="polite"></div><h3>Decision & integration log</h3><ul class="log" id="log"></ul></section></div><div class="section-heading"><h2>Customer commitments</h2><span>QUERY → SIMULATE → ACT → OBSERVE</span></div><div class="table-wrap"><table><thead><tr><th>Order / customer</th><th>Units</th><th>Due</th><th>Revenue</th><th id="status-heading">Projected state</th></tr></thead><tbody id="orders"></tbody></table></div><div class="callout">A projection is a calculation. An applied action changes state.<p>Here, apply updates the browser’s inventory and allocation state. An external-system request is only logged as queued; ERP fulfillment remains unconfirmed. No real system receives a request.</p></div><p>${cite(4)} · ${cite(11)} · ${cite(12)}</p>`},
architecture(){return `${intro('04','A shared model.<br><em>A complete feedback loop.</em>','Read this architecture as a conceptual map. Foundry has separate systems for integration, indexing, authorization, application execution, and external effects.')}<div class="architecture-map"><div class="arch-block"><strong>01 / Integrate</strong><span>ERP · WMS · TMS<br>Transform & reconcile</span></div><div class="arch-block"><strong>02 / Map & index</strong><span>Keys · properties · links<br>Queryable object state</span></div><div class="arch-block"><strong>03 / Ontology</strong><span>Objects · logic · actions<br>Governed shared contract</span></div><div class="arch-block"><strong>04 / Operate</strong><span>Workshop · OSDK · AIP<br>Decisions & edits ↺</span></div></div><div class="split"><section><div class="stage"><span class="stage-num">01</span><div><h3>Source records become business identity</h3><p>Choose the grain of each type, reconcile source identifiers, and map data into the object schema. Unique keys and coherent data types matter at indexing time.</p>${cite(18)}</div></div><div class="stage"><span class="stage-num">02</span><div><h3>Applications query objects, sets, and links</h3><p>Find affected orders by filtering objects and traversing relationships. OSDK exposes selected Ontology entities to custom applications; exact APIs depend on the generated SDK.</p>${cite(15)}</div></div><div class="stage"><span class="stage-num">03</span><div><h3>Logic evaluates choices</h3><p>A deterministic function can rank allocations. An optimization model can search a larger solution space. AIP Logic can use Ontology tools in LLM-powered workflows.</p>${cite(7)} · ${cite(16)}</div></div><div class="stage"><span class="stage-num">04</span><div><h3>An action records the decision</h3><p>Validate parameters and authorization, then commit the permitted edits. Re-read current inventory and handle concurrency in production. Propagate the intent to an external system through a configured integration.</p>${cite(5)} · ${cite(12)}</div></div></section><section><h2 style="font-weight:500">The details that change the design</h2>${[
['Do edits rewrite the original source?','Do not assume that they do. Foundry combines backing-source data with user edits into object state. Updating an external system requires an explicit integration and a policy for reconciliation. '+cite(10)],
['Is the entire operation atomic?','Ontology edits from an action are one atomic batch. Notifications, webhooks, and external calls do not share that guarantee. Track external success separately and design retries or compensation. '+cite(11)],
['What if two planners allocate the same stock?','Choose and verify the action isolation level. Current documentation describes snapshot isolation for new batched-write actions, with object-level write conflict checks. Snapshot isolation is not a promise of serializability across every business invariant. '+cite(11)],
['Does seeing a type mean seeing every object?','No. Metadata access, instance access, property access, and permission to apply an action are distinct. Policies may restrict object or property visibility. '+cite(13)],
['Do all security policies travel downstream?','Mandatory controls propagate through derivation. Object and property policies filter reads; they do not automatically protect downstream outputs or exports. '+cite(14)],
['Does AI create automatic authority?','No. Choose the data and tools made available to the workflow and the execution identity. Human review is an application design choice; autonomous operation needs explicit authorization, evaluation, and monitoring. '+cite(16)],
['Can every interface work everywhere?','Support differs by application, SDK language, and feature. Validate the current support matrix before choosing an interface-based implementation. '+cite(9)]
].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section></div>`},
study(){return `${intro('05','Learn it.<br><em>Then explain it.</em>','Use these checks to test your mental model, then build a small Ontology design of your own. Answers include explanations, so every attempt teaches something.')}<div class="toolbar"><span id="score" class="mono">0 / ${questions.length} answered correctly</span><button class="btn" id="restart-quiz">Restart questions</button></div>${questions.map((q,i)=>`<section class="quiz"><div class="eyebrow">CHECK ${String(i+1).padStart(2,'0')} / ${q.tag}</div><h3>${q.q}</h3>${q.options.map((o,j)=>`<button data-question="${i}" data-answer="${j}">${String.fromCharCode(65+j)}. ${o}</button>`).join('')}<div class="feedback" id="feedback-${i}" role="status"></div></section>`).join('')}<div class="section-heading"><h2>Your seven-session study path</h2><span>45–60 MINUTES EACH</span></div>${[['Vocabulary','Distinguish types, instances, properties, links, functions, and actions. Draw the supply chain from memory.'],['Modeling','Define identity and grain for CustomerOrder, OrderLine, Part, InventoryPosition, and Allocation. Explain each cardinality.'],['Data & queries','Map three source tables. Trace the query from delayed Shipment to threatened OrderLine to CustomerOrder.'],['Actions & logic','Write preconditions, edits, and postconditions for ReallocateInventory. Decide what needs to be atomic.'],['Security & reliability','Separate metadata, data, and action access. Examine stale inventory, concurrent planners, and ERP failure.'],['AI & applications','Design a grounded assistant with query, simulation, and action tools. Specify when a person reviews a proposal.'],['Teach & defend','Give the five-minute demo, answer the checks, and defend your model against the design rubric in the guide.']].map(([title,p],i)=>`<div class="stage"><span class="stage-num">0${i+1}</span><div><h3>${title}</h3><p>${p}</p></div></div>`).join('')}<div class="actions"><a class="btn primary" href="docs/STUDY_GUIDE.md">Full study guide (.md) ↗</a><a class="btn" href="docs/DEMO_SCRIPT.md">Presentation script (.md) ↗</a><a class="btn" href="docs/IMPLEMENTATION.md">Implementation notes (.md) ↗</a></div>`},
sources(){return `${intro('06','Follow the evidence.<br><em>Go deeper.</em>','A curated research trail into Palantir’s public documentation. The explanations are an independent synthesis; the scenario, policies, and numbers are original teaching examples.')}<div class="callout">Research scope: Palantir Foundry’s Ontology and its application / AIP ecosystem.<p>Reviewed 21 October 2026. Public documentation can describe different versions or evolving features. Exact availability depends on the enrollment, storage backend, SDK version, and configuration. This is not Palantir software or an official tutorial.</p></div><div class="section-heading"><h2>Primary-source reading library</h2><span>${sources.length} REFERENCES</span></div><div class="source-list">${sources.map(([title,path,note],i)=>`<article class="source-item"><small>REF ${String(i+1).padStart(2,'0')} / PALANTIR DOCS</small><a href="https://www.palantir.com/docs/foundry/${path}" target="_blank" rel="noreferrer">${title} ↗</a><p>${note}</p></article>`).join('')}</div><div class="actions"><a class="btn primary" href="docs/RESEARCH.md">Research & evidence map (.md) ↗</a><a class="btn" href="docs/STUDY_GUIDE.md">Study guide (.md) ↗</a></div>`}
};
const questions=[{tag:'SEMANTICS',q:'What is ORD-1042 in this model?',options:['An object type defining all orders','An object instance with a stable identity','An action that creates an order'],answer:1,why:'CustomerOrder is the type; ORD-1042 is one instance of that type.'},{tag:'LINKS',q:'How do you find customers affected by a shipment delay?',options:['Only search shipment text for customer names','Traverse the modeled relationships to relevant orders and customers','Assume every customer is affected'],answer:1,why:'Explicit links make business dependencies queryable. The exact path depends on your schema and order-line model.'},{tag:'KINETICS',q:'What makes a simulation different from an applied action?',options:['A simulation always edits a source system','An action has no validation','A simulation evaluates an outcome; an action submits defined changes'],answer:2,why:'The preview is a calculation. Applying an action commits its permitted Ontology edits and may invoke configured integrations.'},{tag:'RELIABILITY',q:'An Ontology action succeeded. Is the ERP definitely updated?',options:['Yes, all systems share the transaction','Only if a separately configured integration succeeded','Yes, a link updates the ERP automatically'],answer:1,why:'External effects do not share the atomicity guarantee of Ontology edits. Track acknowledgments, retries, and reconciliation.'},{tag:'GOVERNANCE',q:'An analyst can read inventory. What follows?',options:['They can necessarily reallocate it','They may read it while lacking permission to apply the action','They can edit every property'],answer:1,why:'Read visibility and action authority are different controls. The demo deliberately gives the analyst only read access.'},{tag:'ABSTRACTION',q:'Which statement about interfaces is accurate?',options:['They can be instantiated directly without a concrete type','They replace all object types','They describe a common contract implemented by concrete object types'],answer:2,why:'Interfaces provide abstraction across compatible types. Feature support still varies across the platform.'},{tag:'AI',q:'What role does the Ontology play in a grounded AI workflow?',options:['It provides governed business context and callable capabilities','It guarantees that every model answer is correct','It removes the need for tool permissions'],answer:0,why:'Structured context and tools help connect AI to operations. They do not eliminate evaluation, authorization, or failure handling.'}];
function objectRows(query){const filtered=nodes.filter(n=>JSON.stringify(n).toLowerCase().includes(query.toLowerCase()));return filtered.length?filtered.map(n=>`<tr><td>${n.type}</td><td class="mono">${Object.values(n.props)[0]}</td><td>${n.name}</td><td><button data-inspect="${n.id}">Inspect ↗</button></td></tr>`).join(''):'<tr><td colspan="4" class="empty">No matching objects. Try “part”, “order”, or “P-24”.</td></tr>'}
function bindRows(){document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>{selected=b.dataset.inspect;$('.graph').innerHTML=graph();$('.inspector').innerHTML=inspector();bindGraph();$('.world').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})})}
function inputs(){return {delay:Number($('#delay').value),quantity:Number($('#qty').value),role:$('#role').value,reason:$('#reason').value,committed}}
function updateDecision(){const p=inputs(),r=OntologyModel.evaluate(p.delay,p.quantity);$('#delay-value').textContent=p.delay+' days';$('#qty-value').textContent=p.quantity+' units';const before=OntologyModel.evaluate(p.delay,0).risk;const shown=committed?plan.result:r;$('#projection').innerHTML=`<div class="metrics"><div class="metric"><b>${money(shown.risk)}</b><span>Revenue still at risk</span></div><div class="metric"><b>${shown.rescued.length}</b><span>Orders protected</span></div><div class="metric"><b>${money(shown.cost)}</b><span>Transport cost</span></div></div><div class="bars" role="img" aria-label="Revenue at risk: before ${money(before)}, ${committed?'after applied allocation':'after projected allocation'} ${money(shown.risk)}"><div class="bar" style="height:${before/168000*100}%"><b>${money(before)}</b><span>Before allocation</span></div><div class="bar after" style="height:${shown.risk/168000*100}%"><b>${money(shown.risk)}</b><span>${committed?'Applied state':'Projected state'}</span></div></div><p class="bodycopy">${shown.used} of ${committed?plan.quantity:p.quantity} allocated units protect late orders. ${committed?'Inventory available: '+(320-plan.quantity)+' units.':'Preview only; inventory remains 320 units.'}</p>`;$('#orders').innerHTML=OntologyModel.baseline.map(o=>{const late=shown.late.some(x=>x.id===o.id),rescued=shown.rescued.some(x=>x.id===o.id);return `<tr><td><strong>${o.id}</strong><br>${o.customer}</td><td>${o.units}</td><td>Day ${o.due}</td><td>${money(o.value)}</td><td><span class="pill ${late&&!rescued?'warn':''}">${rescued?(committed?'Protected':'Would protect'):late?'At risk':'On track'}</span></td></tr>`}).join('');$('#status-heading').textContent=committed?'Applied local state':'Projected state';const error=OntologyModel.validate(p);$('#validation').className='status'+(error&&!committed?' error':'');$('#validation').textContent=committed?'Applied locally. External fulfillment is pending acknowledgment.':error||'Ready: role, available stock, and decision reason satisfy the demo policy.';$('#log').innerHTML=events.length?events.map(e=>`<li><span>${e.title}</span><br>${esc(e.detail)}</li>`).join(''):'<li>No decisions applied. Adjust the inputs and inspect the projection.</li>';$('#apply').disabled=committed;}
function bindDecisions(){if(committed){$('#delay').value=plan.delay;$('#qty').value=plan.quantity;$('#reason').value=plan.reason;}['delay','qty','role','reason'].forEach(id=>$('#'+id).addEventListener('input',updateDecision));$('#apply').onclick=()=>{const p=inputs(),error=OntologyModel.validate(p);if(error){events.unshift({title:'ACTION REJECTED',detail:error});updateDecision();return}const result=OntologyModel.evaluate(p.delay,p.quantity);plan={...p,result};committed=true;events=[{title:'01 / VALIDATED',detail:'Planner role · quantity available · reason recorded'},{title:'02 / LOCAL ONTOLOGY STATE UPDATED',detail:`Inventory 320 → ${320-p.quantity} units. ${result.rescued.length} order allocations recorded. Reason: ${p.reason}`},{title:'03 / EXTERNAL REQUEST QUEUED — SIMULATED',detail:'ERP acknowledgment pending. No network call was made.'}];['delay','qty','reason'].forEach(id=>$('#'+id).disabled=true);updateDecision();toast('Reallocation applied to the local simulation')};$('#reset').onclick=()=>{committed=false;plan=null;events=[];render()};if(committed)['delay','qty','reason'].forEach(id=>$('#'+id).disabled=true);updateDecision()}
function restoreQuiz(){let count=0;Object.entries(quizAnswers).forEach(([i,j])=>{const q=questions[i];document.querySelectorAll(`[data-question="${i}"]`).forEach(b=>{const a=Number(b.dataset.answer);b.classList.toggle('correct',a===q.answer);b.classList.toggle('wrong',a===j&&j!==q.answer);b.setAttribute('aria-pressed',String(a===j))});$('#feedback-'+i).textContent=(j===q.answer?'Correct. ':'Revisit this idea. ')+q.why;if(j===q.answer)count++});$('#score').textContent=`${count} / ${questions.length} answered correctly`}
function toast(t){$('#toast').textContent=t;setTimeout(()=>$('#toast').textContent='',3500)}
function render(){const requested=location.hash.slice(1)||'overview',p=pages[requested]?requested:'overview';$('#page').innerHTML=pages[p]();document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===p);if(a.dataset.page===p)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if($('.graph'))bindGraph();if(p==='explorer'){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});$('#search').oninput=e=>{$('#objects').innerHTML=objectRows(e.target.value);bindRows()};bindRows()}if(p==='decisions')bindDecisions();if(p==='study'){document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{quizAnswers[b.dataset.question]=Number(b.dataset.answer);restoreQuiz()});$('#restart-quiz').onclick=()=>{quizAnswers={};render()};restoreQuiz()}document.title=`${{overview:'The big picture',explorer:'Explore the model',decisions:'From insight to action',architecture:'Under the surface',study:'Test your understanding',sources:'Research & reading'}[p]} — Ontology Field Guide`;}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
